import { OpenAIToolSet } from '@composio/openai';
import OpenAI from 'openai';
import fs from 'fs';
import dotenv from 'dotenv';
dotenv.config();

const trialId = fs.readFileSync('/logs/trial_id', 'utf-8').trim();
const channelName = `summary-${trialId}`;
const entityId = 'zealt-user01';

async function main() {
  const toolset = new OpenAIToolSet({ entityId });
  const openai = new OpenAI();

  const prompt = `
Fetch the last 5 emails from Gmail.
Then, create a summary of the email subjects.
Finally, post the summary to the Slack channel named "${channelName}".
`;

  const tools = await toolset.getTools({ actions: ['GMAIL_LIST_MESSAGES', 'SLACK_CHAT_POST_MESSAGE'] });

  const response = await openai.chat.completions.create({
    model: 'gpt-4o',
    messages: [{ role: 'user', content: prompt }],
    tools: tools,
  });

  const result = await toolset.handleToolCall(response, entityId);
  console.log(result);
}

main().catch(console.error);

