import { Composio } from '@composio/core';
import fs from 'fs';
import dotenv from 'dotenv';
dotenv.config();

const trialId = fs.readFileSync('/logs/trial_id', 'utf-8').trim();
const channelName = `summary-${trialId}`;
const entityId = 'zealt-user01';

async function main() {
  const composio = new Composio();

  console.log("Fetching emails...");
  const emailsResponse = await composio.actions.execute({
    action: "GMAIL_LIST_MESSAGES",
    params: { maxResults: 5 },
    entityId: entityId
  });

  const messages = emailsResponse.data || emailsResponse.response_data || emailsResponse;
  console.log("Messages fetched:", JSON.stringify(messages).substring(0, 200));

  let summary = `Summary of last 5 emails:\n`;

  if (Array.isArray(messages)) {
    messages.forEach((msg: any, index: number) => {
      summary += `${index + 1}. ${msg.subject || msg.snippet || 'No subject'}\n`;
    });
  } else if (messages.messages && Array.isArray(messages.messages)) {
    messages.messages.forEach((msg: any, index: number) => {
      summary += `${index + 1}. ${msg.subject || msg.snippet || 'No subject'}\n`;
    });
  } else {
    summary += JSON.stringify(messages).substring(0, 500);
  }

  console.log("Summary:", summary);

  console.log("Posting to Slack...");
  const slackResponse = await composio.actions.execute({
    action: "SLACK_CHAT_POST_MESSAGE",
    params: {
      channel: channelName,
      text: summary
    },
    entityId: entityId
  });

  console.log("Slack response:", slackResponse);
}

main().catch(console.error);

